const { createRequestHandler } = require('expo-server/adapter/vercel');
const path = require('path');
const fs = require('fs');

// Locate the exported server bundle directory generated by `expo export -p web`
const serverBuildPath = fs.existsSync(path.resolve(__dirname, '../dist/server'))
  ? path.resolve(__dirname, '../dist/server')
  : path.resolve(process.cwd(), 'dist/server');

const handler = createRequestHandler({
  build: serverBuildPath,
});

module.exports = handler;
module.exports.default = handler;
